  display: flex;
  flex-direction: column;
  height:90%;
  width:100%;
  padding: 0.8rem;
  overflow-y: scroll;
  scroll-timeline: --page-scroll y;
  scroll-timeline: --page-scroll vertical;
}

@keyframes grow-progress {
	0% {
    scale: 1 0;
  }

  100% {
    scale: 1 1;
  }
}

.progress {
	position: fixed;
	left: 0.4rem; 
  /* top: -1rem; */
  bottom: 2.5rem;
	height: 90vh; 
  width: 0.8em;
  border: 0rem;
  border-radius: 4rem;
	background: #f3f0f8;
  opacity: 0.5;
  /* transform: scaleX(0); */
	transform-origin:center 100%;
	animation: grow-progress auto linear;
	animation-timeline: --page-scroll;
}

