  flex-direction: row;
  justify-content: center;
}

#overlay {
  transition: all .3s ease-in-out;
}

.summaryCard:hover {
  background: rgb(255,255,255);
  background: linear-gradient(90deg, rgba(255,255,255,1) 0%, rgba(91,140,255,0.2) 100%);
}

